paras = doc.paragraphs
for heading, texts in additions.items():
    anchor = next((p for p in paras if p.text.strip().casefold() == heading.casefold()), None)
    if anchor is None:
        # Subsection title may use terminal punctuation in the document.
        anchor = next((p for p in paras if p.text.strip().rstrip('.').casefold() == heading.rstrip('.').casefold()), None)
    if anchor is None:
        raise RuntimeError(f"Missing insertion point: {heading}")
    for text in texts:
        new = anchor.insert_paragraph_before(text, style='Normal')
        new.paragraph_format.space_before = Pt(0)
        new.paragraph_format.space_after = Pt(0)
        new.paragraph_format.line_spacing = 1
        for run in new.runs:
            run.font.name = 'Times New Roman'
            run._element.rPr.rFonts.set(qn('w:eastAsia'), 'Times New Roman')
            run.font.size = Pt(12)
            run.font.color.rgb = RGBColor(0, 0, 0)
        paras.insert(paras.index(anchor), new)

doc.save(path)
print(f"Added {sum(map(len, additions.values()))} paragraphs ({sum(len(t.split()) for vs in additions.values() for t in vs)} words)")
